package de.lazytv.pro.catalog;
import java.io.*;import java.util.*;import java.util.regex.*;
public final class M3uParser {private static final Pattern A=Pattern.compile("([\\w-]+)=\\\"([^\\\"]*)\\\"");private M3uParser(){}public static Catalog parse(BufferedReader r)throws Exception{Catalog c=new Catalog();Map<String,String> cats=new LinkedHashMap<>();String line,info=null;while((line=r.readLine())!=null){line=line.trim();if(line.startsWith("#EXTINF:")){info=line;}else if(info!=null&&!line.isEmpty()&&!line.startsWith("#")){Map<String,String>m=new HashMap<>();Matcher x=A.matcher(info);while(x.find())m.put(x.group(1).toLowerCase(Locale.US),x.group(2));int comma=info.lastIndexOf(',');String name=m.get("tvg-name");if(name==null||name.isEmpty())name=comma>=0?info.substring(comma+1).trim():"Stream";String group=m.get("group-title");if(group==null||group.isEmpty())group="Të tjera";CatalogType type=type(group,line);String key=type.name()+"|"+group;if(!cats.containsKey(key)){String id="m3u-"+Integer.toHexString(key.hashCode());cats.put(key,id);c.categories.add(new Category(id,group,type));}String id="m3u-"+Integer.toHexString((name+line).hashCode());c.items.add(CatalogItems.create(id,name,cats.get(key),m.get("tvg-logo"),line,m.get("tvg-id"),type));info=null;}}if(c.items.isEmpty())throw new CatalogException("Playlist M3U është bosh ose e pavlefshme");return c;}private static CatalogType type(String g,String u){String s=(g==null?"":g).toLowerCase(Locale.US);if(s.contains("series")||s.contains("serial")||s.contains("episode"))return CatalogType.SERIES;if(s.contains("movie")||s.contains("vod")||s.contains("film"))return CatalogType.MOVIES;return CatalogType.LIVE;}}
